import { describe, it, expect, beforeEach, vi } from 'vitest';
import { computeVelocity, updateCadenceForVelocity, VelocityResult } from './enforcement-velocity';

describe('computeVelocity', () => {
  describe('basic velocity computation', () => {
    it('should return zero velocity for empty arrivals', () => {
      const result = computeVelocity([]);
      expect(result.velocity).toBe(0);
    });

    it('should return zero velocity for single arrival', () => {
      const result = computeVelocity([Date.now()]);
      expect(result.velocity).toBe(0);
    });

    it('should compute positive velocity for two arrivals', () => {
      const now = Date.now();
      const result = computeVelocity([now - 1000, now]);
      expect(result.velocity).toBeGreaterThan(0);
    });
  });

  describe('acceleration detection', () => {
    it('should detect accelerating arrivals (intervals shrinking)', () => {
      const now = Date.now();
      // Intervals: 1000ms, 500ms, 250ms (accelerating)
      const arrivals = [now - 1750, now - 750, now];
      const result = computeVelocity(arrivals);
      expect(result.velocity).toBeGreaterThan(0);
      expect(result.acceleration).toBeGreaterThan(0);
    });

    it('should detect decelerating arrivals (intervals expanding)', () => {
      const now = Date.now();
      // Intervals: 250ms, 500ms, 1000ms (decelerating)
      const arrivals = [now - 1750, now - 1500, now - 1000, now];
      const result = computeVelocity(arrivals);
      expect(result.acceleration).toBeLessThanOrEqual(0);
    });

    it('should detect constant velocity (equal intervals)', () => {
      const now = Date.now();
      // All intervals 1000ms
      const arrivals = [now - 3000, now - 2000, now - 1000, now];
      const result = computeVelocity(arrivals);
      expect(Math.abs(result.acceleration)).toBeLessThan(0.1);
    });
  });

  describe('high velocity scenarios', () => {
    it('should produce high velocity score for rapid successive arrivals', () => {
      const now = Date.now();
      // 5 arrivals in 100ms window
      const arrivals = [now - 100, now - 75, now - 50, now - 25, now];
      const result = computeVelocity(arrivals);
      expect(result.velocity).toBeGreaterThan(0.5);
    });

    it('should produce low velocity score for sparse arrivals', () => {
      const now = Date.now();
      const oneHour = 60 * 60 * 1000;
      // Arrivals spaced 1 hour apart
      const arrivals = [now - 3 * oneHour, now - 2 * oneHour, now - oneHour, now];
      const result = computeVelocity(arrivals);
      expect(result.velocity).toBeLessThan(0.2);
    });
  });

  describe('timestamp handling', () => {
    it('should handle out-of-order timestamps by sorting', () => {
      const now = Date.now();
      const unsorted = [now, now - 1000, now - 500];
      const sorted = [now - 1000, now - 500, now];

      const resultUnsorted = computeVelocity(unsorted);
      const resultSorted = computeVelocity(sorted);

      expect(resultUnsorted.velocity).toBe(resultSorted.velocity);
    });

    it('should handle duplicate timestamps', () => {
      const now = Date.now();
      const arrivals = [now - 2000, now - 1000, now - 1000, now];
      const result = computeVelocity(arrivals);
      expect(result.velocity).toBeDefined();
      expect(isNaN(result.velocity)).toBe(false);
    });

    it('should handle very recent arrivals (millisecond resolution)', () => {
      const now = Date.now();
      const arrivals = [now - 10, now - 5, now];
      const result = computeVelocity(arrivals);
      expect(result.velocity).toBeGreaterThan(0);
      expect(isNaN(result.velocity)).toBe(false);
    });
  });

  describe('domain and jurisdiction grouping', () => {
    it('should compute velocity per domain-jurisdiction pair', () => {
      const now = Date.now();
      const data = [
        { domain: 'domain1', jurisdiction: 'us-ca', arrivals: [now - 1000, now] },
        { domain: 'domain1', jurisdiction: 'us-ny', arrivals: [now - 5000, now - 4000, now - 3000, now - 2000, now] },
      ];

      const result1 = computeVelocity(data[0].arrivals);
      const result2 = computeVelocity(data[1].arrivals);

      // us-ny has more arrivals (higher velocity)
      expect(result2.velocity).toBeGreaterThan(result1.velocity);
    });
  });

  describe('edge cases and validation', () => {
    it('should handle null or undefined gracefully', () => {
      expect(() => computeVelocity(null as any)).not.toThrow();
      expect(() => computeVelocity(undefined as any)).not.toThrow();
    });

    it('should handle very old timestamps', () => {
      const oneWeekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
      const arrivals = [oneWeekAgo, oneWeekAgo + 1000, oneWeekAgo + 2000];
      const result = computeVelocity(arrivals);
      expect(isNaN(result.velocity)).toBe(false);
    });

    it('should return consistent results for same input', () => {
      const now = Date.now();
      const arrivals = [now - 2000, now - 1000, now];
      const result1 = computeVelocity(arrivals);
      const result2 = computeVelocity(arrivals);
      expect(result1.velocity).toBe(result2.velocity);
    });
  });
});

describe('updateCadenceForVelocity', () => {
  describe('cadence hour adjustment', () => {
    it('should lower cadence_hours when velocity is high', async () => {
      const currentCadence = 24;
      const velocity = 0.8;
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        velocity,
        currentCadence
      );
      expect(result.newCadenceHours).toBeLessThan(currentCadence);
    });

    it('should raise cadence_hours when velocity is low', async () => {
      const currentCadence = 12;
      const velocity = 0.1;
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        velocity,
        currentCadence
      );
      expect(result.newCadenceHours).toBeGreaterThan(currentCadence);
    });

    it('should keep cadence unchanged for medium velocity', async () => {
      const currentCadence = 24;
      const velocity = 0.4;
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        velocity,
        currentCadence
      );
      expect(Math.abs(result.newCadenceHours - currentCadence)).toBeLessThan(5);
    });
  });

  describe('floor and ceiling constraints', () => {
    it('should never lower cadence below 6 hours (floor)', async () => {
      const currentCadence = 8;
      const velocity = 1.0; // Maximum velocity
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        velocity,
        currentCadence
      );
      expect(result.newCadenceHours).toBeGreaterThanOrEqual(6);
    });

    it('should never raise cadence above ceiling (72 hours)', async () => {
      const currentCadence = 70;
      const velocity = 0.0; // Minimum velocity
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        velocity,
        currentCadence
      );
      expect(result.newCadenceHours).toBeLessThanOrEqual(72);
    });

    it('should clamp initial cadence to valid range', async () => {
      const velocityLow = 0.1;
      const velocityHigh = 0.9;

      const result1 = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        velocityHigh,
        2 // Below floor
      );
      expect(result1.newCadenceHours).toBeGreaterThanOrEqual(6);

      const result2 = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        velocityLow,
        100 // Above ceiling
      );
      expect(result2.newCadenceHours).toBeLessThanOrEqual(72);
    });
  });

  describe('alert urgency', () => {
    it('should raise alert urgency when velocity is high', async () => {
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        0.85,
        24
      );
      expect(result.alertUrgency).toBe('high');
    });

    it('should lower alert urgency when velocity is low', async () => {
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        0.1,
        24
      );
      expect(result.alertUrgency).toBe('low');
    });

    it('should set medium urgency for moderate velocity', async () => {
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        0.45,
        24
      );
      expect(['low', 'medium', 'high']).toContain(result.alertUrgency);
    });
  });

  describe('database write behavior', () => {
    it('should write updated cadence to hive_scout_sources', async () => {
      const domain = 'test-domain';
      const jurisdiction = 'us-ca';
      const result = await updateCadenceForVelocity(
        { domain, jurisdiction },
        0.7,
        24
      );
      expect(result.writeSuccess).toBe(true);
      expect(result.affectedRows).toBeGreaterThan(0);
    });

    it('should handle database write failures gracefully', async () => {
      // Mock a DB failure scenario
      const result = await updateCadenceForVelocity(
        { domain: 'nonexistent-domain', jurisdiction: 'invalid-jurisdiction' },
        0.5,
        24
      );
      // Should return a result even if write fails (fail-soft)
      expect(result).toHaveProperty('newCadenceHours');
      expect(result).toHaveProperty('alertUrgency');
    });

    it('should update multiple jurisdiction records for same domain', async () => {
      const domain = 'test-domain';
      const jurisdictions = ['us-ca', 'us-ny', 'us-tx'];

      const results = await Promise.all(
        jurisdictions.map(jurisdiction =>
          updateCadenceForVelocity(
            { domain, jurisdiction },
            0.6,
            24
          )
        )
      );

      results.forEach(result => {
        expect(result.newCadenceHours).toBeLessThan(24);
      });
    });
  });

  describe('integration: velocity → cadence update', () => {
    it('should correlate high velocity with low cadence', async () => {
      const domain = { domain: 'test-domain', jurisdiction: 'us-ca' };
      const lowVelocity = 0.2;
      const highVelocity = 0.9;

      const resultLow = await updateCadenceForVelocity(domain, lowVelocity, 24);
      const resultHigh = await updateCadenceForVelocity(domain, highVelocity, 24);

      expect(resultHigh.newCadenceHours).toBeLessThan(resultLow.newCadenceHours);
    });

    it('should produce consistent results across multiple calls', async () => {
      const domain = { domain: 'test-domain', jurisdiction: 'us-ca' };
      const velocity = 0.65;
      const cadence = 24;

      const result1 = await updateCadenceForVelocity(domain, velocity, cadence);
      const result2 = await updateCadenceForVelocity(domain, velocity, cadence);

      expect(result1.newCadenceHours).toBe(result2.newCadenceHours);
    });
  });

  describe('boundary conditions', () => {
    it('should handle velocity = 0.0', async () => {
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        0.0,
        24
      );
      expect(result.newCadenceHours).toBeDefined();
      expect(result.newCadenceHours).toBeGreaterThanOrEqual(6);
    });

    it('should handle velocity = 1.0', async () => {
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        1.0,
        24
      );
      expect(result.newCadenceHours).toBeDefined();
      expect(result.newCadenceHours).toBeLessThanOrEqual(72);
    });

    it('should handle velocity > 1.0 (extrapolated acceleration)', async () => {
      const result = await updateCadenceForVelocity(
        { domain: 'test-domain', jurisdiction: 'us-ca' },
        1.5,
        24
      );
      expect(result.newCadenceHours).toBeGreaterThanOrEqual(6);
      expect(result.alertUrgency).toBe('high');
    });
  });
});

describe('integration: computeVelocity → updateCadence workflow', () => {
  it('should compute velocity from arrivals and use it to update cadence', async () => {
    const now = Date.now();
    // Simulating 5 rapid regulatory fact arrivals
    const arrivals = [now - 100, now - 75, now - 50, now - 25, now];
    const velocity = computeVelocity(arrivals);

    const result = await updateCadenceForVelocity(
      { domain: 'compliance-heavy-domain', jurisdiction: 'us-ca' },
      velocity.velocity,
      24 // Current cadence
    );

    // High velocity should lower cadence
    expect(result.newCadenceHours).toBeLessThan(24);
    expect(result.alertUrgency).toBe('high');
  });

  it('should handle domain with no recent activity', async () => {
    const now = Date.now();
    // Single arrival or very sparse arrivals
    const arrivals = [now - 86400000]; // 1 day old
    const velocity = computeVelocity(arrivals);

    const result = await updateCadenceForVelocity(
      { domain: 'quiet-domain', jurisdiction: 'us-ca' },
      velocity.velocity,
      6 // Already at floor
    );

    // Low velocity should not lower cadence below floor
    expect(result.newCadenceHours).toBeGreaterThanOrEqual(6);
  });
});
